@php
    $services = collect($paymentServices ?? []);
    $sessions = collect($paymentSessions ?? []);
    $paymentResult = session('adminPaymentResult');
    $currentPaymentSession = $paymentSession ?? session('system_session');
    $metrics = $paymentMetrics ?? [];
    $filters = $paymentFilters ?? [];
    $currency = function ($value) {
        return '₦' . number_format((float) $value, 2);
    };
    $composerOpen = $errors->any() || is_array($paymentResult) || request()->boolean('create');
    $pendingPayments = isset($payments) && method_exists($payments, 'getCollection')
        ? $payments->getCollection()->filter(function ($payment) {
            return in_array(strtolower((string) ($payment->status ?? '')), ['pending', 'processing'], true)
                && trim((string) ($payment->rrr ?? '')) !== '';
        })
        : collect();
