                    <tr><td><strong>{{ $payment->created_at ? \Carbon\Carbon::parse($payment->created_at)->format('d M Y') : '—' }}</strong><span class="ap-sub">{{ $payment->created_at ? \Carbon\Carbon::parse($payment->created_at)->format('h:i A') : '' }}</span></td><td><div class="ap-person" title="{{ $displayName }}">{{ $displayName }}</div><span class="ap-sub">{{ $studentNumber ?: ($payment->email ?: ($payment->phone ?: 'External payer')) }}</span></td><td><div class="ap-description" title="{{ $payment->description ?: 'Payment' }}">{{ $payment->description ?: 'Payment' }}</div><span class="ap-sub">{{ $payment->payment_method ?: 'Remita' }}</span></td><td>{{ $payment->session ?: '—' }}</td><td><strong>{{ $payment->rrr ?: '—' }}</strong><span class="ap-sub">{{ $payment->orderId ?: '' }}</span></td><td class="ap-amount">{{ $currency($displayAmount) }}</td><td><span class="ap-status {{ $statusClass }}">{{ $payment->status ?: 'Unknown' }}</span></td><td><div class="ap-actions">@if(in_array(strtolower((string) $payment->status), ['pending','processing'], true) && $payment->rrr)<form method="POST" action="{{ route('admin.make-payment.verify', $payment->id) }}" class="ap-action-form js-admin-action-form">@csrf<button class="btn btn-info text-white" type="submit" data-loading="Checking..."><i class="fas fa-shield-check"></i> Verify</button></form>@endif @if(in_array(strtolower((string) $payment->status), ['pending','processing'], true))<form method="POST" action="{{ route('admin.make-payment.cancel', $payment->id) }}" class="ap-action-form js-admin-action-form" data-confirm="Cancel this pending payment? It will remain in the records as cancelled.">@csrf<button class="btn btn-outline-danger" type="submit" data-loading="Cancelling..."><i class="fas fa-ban"></i> Cancel</button></form>@endif @if(!in_array(strtolower((string) $payment->status), ['pending','processing'], true))<span class="text-muted small">No action</span>@endif</div></td></tr>
                @empty
                    <tr><td colspan="8"><div class="ap-empty"><i class="fas fa-receipt"></i><strong>No payment transactions found</strong><div>Try clearing the filters or searching with another reference.</div></div></td></tr>
                @endforelse
            </tbody></table></div>
            @if(isset($payments) && method_exists($payments, 'links'))<div class="ap-pagination">{{ $payments->onEachSide(1)->links('pagination::bootstrap-4') }}</div>@endif
        </section>
        <p class="ap-rules mt-3 mb-0"><strong>Payment status:</strong> A record is complete only after Remita confirms the payment. Pending invoices remain available for follow-up and do not count as paid collections.</p>
