<script>
(function(){
    const service = document.getElementById('service_type');
    const amount = document.getElementById('amount');
    const description = document.getElementById('description');
    if(service){ service.addEventListener('change', function(){ const option=this.options[this.selectedIndex]; const configured=parseFloat(option?.dataset.amount || '0'); if(configured>0 && (!amount.value || Number(amount.value)===0)) amount.value=configured.toFixed(2); if(option?.dataset.description && !description.value) description.value=option.dataset.description; }); }
    const form=document.getElementById('adminPaymentForm'); const submit=document.getElementById('adminPaymentSubmit'); if(form&&submit){ form.addEventListener('submit', function(){ submit.disabled=true; submit.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i> Creating invoice...'; }); }
    document.querySelectorAll('.js-admin-action-form').forEach(function(actionForm){ actionForm.addEventListener('submit', function(event){ const message=this.dataset.confirm; if(message&&!window.confirm(message)){ event.preventDefault(); return; } const button=this.querySelector('button[type="submit"]'); if(button){ button.disabled=true; button.innerHTML='<i class="fas fa-spinner fa-spin"></i> '+(button.dataset.loading||'Processing...'); } }); });
    const composer=document.getElementById('adminPaymentComposer'); const composerToggle=document.querySelector('.ap-composer-toggle'); if(composer&&composerToggle){ const setComposer=function(open){ composer.classList.toggle('show',open); composer.style.display=open?'block':'none'; composerToggle.setAttribute('aria-expanded',open?'true':'false'); const label=composerToggle.querySelector('span'); if(label) label.textContent=open?'Hide form':'New payment'; }; setComposer({{ $composerOpen ? 'true' : 'false' }}); composerToggle.addEventListener('click',function(){ setComposer(!composer.classList.contains('show')); }); }
    const filterToggle=document.getElementById('paymentFilterToggle'); const paymentFilter=document.getElementById('paymentFilterForm'); if(filterToggle&&paymentFilter){ filterToggle.addEventListener('click', function(){ paymentFilter.classList.toggle('is-open'); }); }
    document.querySelectorAll('.js-pending-paynow').forEach(function(payButton){ payButton.addEventListener('click', async function(){ const rrr=this.dataset.rrr; const original=this.innerHTML; this.disabled=true; this.innerHTML='<i class="fas fa-spinner fa-spin"></i> Opening...'; try{ const started=Date.now(); while(typeof window.RmPaymentEngine==='undefined' && Date.now()-started<15000){ await new Promise(resolve=>setTimeout(resolve,150)); } if(typeof window.RmPaymentEngine==='undefined') throw new Error('The Remita payment service is taking too long to load.'); const engine=window.RmPaymentEngine.init({key:@json(config('services.remita.public_key')),processRrr:true,channels:'card,bank,branch,ussd,qr,ibank,paywithremita,buyoncredit,wallet,phonenumber,transfer,enaira',transactionId:'UG-ADMIN-'+Date.now(),extendedData:{customFields:[{name:'rrr',value:rrr}]},onSuccess:function(){window.location.href='{{ url('/verify') }}?rrr='+encodeURIComponent(rrr);},onError:function(response){payButton.disabled=false;payButton.innerHTML=original;alert((response&&(response.message||response.error))||'Payment was not completed.');},onClose:function(){payButton.disabled=false;payButton.innerHTML=original;}}); engine.showPaymentWidget(); }catch(error){ this.disabled=false; this.innerHTML=original; alert(error.message||'The Remita payment service is unavailable.'); } }); });
    const payButton=document.querySelector('.js-admin-paynow'); if(payButton){ payButton.addEventListener('click', async function(){ const rrr=this.dataset.rrr; const original=this.innerHTML; this.disabled=true; this.innerHTML='<i class="fas fa-spinner fa-spin mr-1"></i> Opening Remita...'; try{ const started=Date.now(); while(typeof window.RmPaymentEngine==='undefined' && Date.now()-started<15000){ await new Promise(resolve=>setTimeout(resolve,150)); } if(typeof window.RmPaymentEngine==='undefined') throw new Error('The Remita payment service is taking too long to load.'); const engine=window.RmPaymentEngine.init({key:@json(config('services.remita.public_key')),processRrr:true,channels:'card,bank,branch,ussd,qr,ibank,paywithremita,buyoncredit,wallet,phonenumber,transfer,enaira',transactionId:'UG-ADMIN-'+Date.now(),extendedData:{customFields:[{name:'rrr',value:rrr}]},onSuccess:function(){window.location.href='{{ url('/verify') }}?rrr='+encodeURIComponent(rrr);},onError:function(response){payButton.disabled=false;payButton.innerHTML=original;alert((response&&(response.message||response.error))||'Payment was not completed.');},onClose:function(){payButton.disabled=false;payButton.innerHTML=original;}}); engine.showPaymentWidget(); }catch(error){ this.disabled=false; this.innerHTML=original; alert(error.message||'The Remita payment service is unavailable.'); } }); }
})();
